#!/usr/bin/env node
/**
 * Tests for scripts/hook-fires.mjs: the table over `<config>/.cache/hook-fires.log` and `--delete`.
 * Each case points CLAUDE_CONFIG_DIR at its own temp directory.
 *
 * Generated by Claude Code at the user's request.
 */

import { test } from 'node:test';
import assert from 'node:assert/strict';
import { spawnSync } from 'node:child_process';
import { mkdtempSync, mkdirSync, writeFileSync, existsSync, rmSync } from 'node:fs';
import { join, dirname } from 'node:path';
import { tmpdir } from 'node:os';
import { fileURLToPath } from 'node:url';

const SCRIPT = join(dirname(fileURLToPath(import.meta.url)), '..', 'scripts', 'hook-fires.mjs');
const created = [];

process.on('exit', () => {
  for (const dir of created) {
    try { rmSync(dir, { recursive: true, force: true }); } catch { /* tmp, let the OS have it */ }
  }
});

function config() {
  const dir = mkdtempSync(join(tmpdir(), 'hook-fires-'));
  created.push(dir);
  mkdirSync(join(dir, '.cache'));
  return dir;
}

const run = (dir, ...args) => spawnSync(process.execPath, [SCRIPT, ...args], { env: { ...process.env, CLAUDE_CONFIG_DIR: dir }, encoding: 'utf8' });
const fire = (day, hook, decision, sub = false, event = 'PreToolUse') => JSON.stringify({ day, hook, event, decision, sub });

test('given a log with a truncated line, when the table is printed, then fires, decisions, main/sub and days are aggregated per hook', () => {
  // Given
  const dir = config();
  writeFileSync(join(dir, '.cache', 'hook-fires.log'), [
    fire('2026-11-01', 'guard-shell', 'silent'),
    fire('2026-11-01', 'guard-shell', 'ask'),
    fire('2026-11-02', 'guard-shell', 'silent', true),
    '{"day":"2026-11-02","hook":"guard-sh',
    fire('2026-11-02', 'done-claim', 'block', false, 'Stop'),
  ].join('\n') + '\n');
  // When
  const r = run(dir);
  // Then
  const rows = r.stdout.trim().split('\n').map((l) => l.split('|').map((c) => c.trim()));
  assert.deepEqual(rows[0], ['hook', 'event', 'fires', 'by decision', 'main/sub', 'days']);
  assert.deepEqual(rows[1], ['done-claim', 'Stop', '1', 'block 1', '1/0', '1']);
  assert.deepEqual(rows[2], ['guard-shell', 'PreToolUse', '3', 'silent 2, ask 1', '2/1', '2']);
  assert.equal(rows.length, 3);
});

test('given a log and the closed sentinel, when --delete runs, then both are gone and it prints deleted', () => {
  // Given
  const dir = config();
  writeFileSync(join(dir, '.cache', 'hook-fires.log'), `${fire('2026-11-01', 'guard-shell', 'silent')}\n`);
  writeFileSync(join(dir, '.cache', 'hook-fires.closed'), '');
  // When
  const r = run(dir, '--delete');
  // Then
  assert.equal(r.stdout.trim(), 'deleted');
  assert.ok(!existsSync(join(dir, '.cache', 'hook-fires.log')));
  assert.ok(!existsSync(join(dir, '.cache', 'hook-fires.closed')));
});
